'use strict';
/** Member-specific opt-in alert delivery. Never uses the legacy ALERT_EMAIL
 * administrator recipient. Only member-confirmed destination emails qualify.
 * The job snapshot is already generated by the existing scanner.
 */
const core=require('./core');
const {send}=require('../../api/secretj-email');
const MAX_RECIPIENTS=15;
const {isMatch,hasFilters}=require('../../dist/assets/secretj-job-preferences');
function matches(job,p){return isMatch(job,p);}
function jobKey(j){
  const key=String(j.url||j.apply_url||j.link||j.id||'');
  return key.length<=500?key:key.slice(0,500);
}
function safeLink(j){
  try{const u=new URL(String(j.url||j.apply_url||''));return u.protocol==='https:'?u.href:'';}catch{return '';}
}
async function deliver(env,sendImpl=send){
  if(process.env.SECRETJ_ALERTS_ENABLED!=='true')return {status:'disabled'};
  if(!process.env.RESEND_API_KEY||!process.env.SECRETJ_EMAIL_FROM)return {status:'not_configured'};
  const response=await env.ASSETS.fetch(new Request('https://jobhunter-youssef.example/data.json'));
  if(!response.ok)return {status:'snapshot_unavailable'};
  const snapshot=await response.json();
  const generated=Date.parse(snapshot.generated_at||'');
  if(!Number.isFinite(generated)||Date.now()-generated>4*60*60*1000)
    return {status:'stale_snapshot'};
  const since=Date.now()-3*60*60*1000;
  const jobs=(snapshot.jobs||[]).filter(j=>
    Date.parse(j.discovered_at||j.detected||'')>=since&&
    Boolean(safeLink(j))).slice(0,2500);
  if(!jobs.length)return {status:'no_new_jobs'};
  const users=await core.query(
    `SELECT u.id,u.email AS email,
              p.egypt_only,p.internships,p.role_families,p.max_experience_years
       FROM public.sj_users u
       JOIN public.sj_preferences p ON p.user_id=u.id
       JOIN public.sj_email_verifications v ON v.user_id=u.id
      WHERE u.is_active=true AND p.email_alerts=true AND v.verified_at IS NOT NULL
        AND lower(COALESCE(v.verified_email,v.recipient_email,u.email))=lower(u.email)
      ORDER BY p.updated_at DESC LIMIT 100`
  );
  let delivered=0,failed=0;
  for(const user of users){
    if(delivered>=MAX_RECIPIENTS)break;
    if(!hasFilters(user))continue;
    const available=jobs.filter(j=>matches(j,user)).sort((a,b)=>Date.parse(b.discovered_at||b.detected||0)-Date.parse(a.discovered_at||a.detected||0)).slice(0,4);
    if(!available.length)continue;
    const reserved=[];
    for(const job of available){
      const key=jobKey(job);
      if(!key)continue;
      const records=await core.query(
        `INSERT INTO public.sj_email_alert_log(user_id,job_key,status)
         VALUES($1,$2,'pending')
         ON CONFLICT(user_id,job_key) DO UPDATE
           SET status='pending',attempted_at=now()
         WHERE sj_email_alert_log.status IN ('failed','pending')
           AND sj_email_alert_log.attempted_at < now()-interval '4 hours'
         RETURNING job_key`,[user.id,key]
      );
      if(records[0])reserved.push({key,job});
    }
    if(!reserved.length)continue;
    const msg=reserved.map(({job})=>
      String(job.title||'Role')+' at '+String(job.company||'Employer')+
      '\n'+safeLink(job)).join('\n\n');
    try{
      // Send only to the registered account email after verification.
      await sendImpl(user.email,'Secret J: New job opportunities',
        'Here are relevant new roles from Job Hunter:\n\n'+msg+
        '\n\nTo stop alerts, open your Secret J account preferences and turn off Email Alerts.');
      for(const item of reserved)await core.query(
        `UPDATE public.sj_email_alert_log
         SET status='sent',sent_at=now()
         WHERE user_id=$1 AND job_key=$2 AND status='pending'`,
        [user.id,item.key]
      );
      delivered++;
    }catch{
      failed++;
      for(const item of reserved)await core.query(
        `UPDATE public.sj_email_alert_log SET status='failed'
         WHERE user_id=$1 AND job_key=$2 AND status='pending'`,
        [user.id,item.key]
      ).catch(()=>{});
    }
  }
  return {status:'processed',delivered,failed};
}
module.exports={deliver,matches,jobKey};
